const bfMoney=n=>'৳'+Number(n).toLocaleString('en-BD'),bfRead=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}},bfSave=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
let bfCart=bfRead('buyfinix-cart',[]);const bfProduct=id=>BF_PRODUCTS.find(p=>p.id===Number(id));
function bfHeader(){const page=location.pathname.split('/').pop()||'index.html',active=x=>page===x?' aria-current="page"':'';return `<div class="announcement">⚡ Fast delivery after payment confirmation · WhatsApp support</div><header class="nav shell shared-nav"><a class="brand" href="index.html">BUY <i>⚡</i> FINIX</a><button class="hamburger" id="global-menu" aria-label="Open menu">☰</button><nav><a href="index.html"${active('index.html')}>Home</a><a href="shop.html"${active('shop.html')}>Shop</a><div class="nav-drop"><button aria-haspopup="true">Categories <span>⌄</span></button><div class="drop-panel"><a href="shop.html?category=subscriptions">Subscriptions</a><a href="shop.html?category=combos">Combo Packs</a><a href="shop.html?category=software">Software</a><a href="shop.html?category=music">Music</a><a href="shop.html?category=adult">Adult</a><a href="shop.html?category=more">More Plans</a></div></div><div class="nav-drop"><button aria-haspopup="true">Quick Links <span>⌄</span></button><div class="drop-panel"><a href="legal.html#login">Login Terms</a><a href="about.html">About Us</a><a href="contact.html">Contact Us</a><a href="legal.html#terms">Terms &amp; Conditions</a></div></div></nav><div class="nav-actions"><button id="global-search" aria-label="Search">⌕</button><a href="account.html"${active('account.html')}>♙ <span>My Account</span></a><button class="header-cart" id="global-cart" aria-label="Open cart">🛒<b data-cart-count>${bfCart.reduce((n,x)=>n+x.qty,0)}</b></button></div></header>`}
function bfFooter(){return `<footer class="site-footer"><div class="shell footer-top"><div><a class="brand light" href="index.html">BUY <i>⚡</i> FINIX</a><p>Digital subscriptions and software for Bangladesh, supported on WhatsApp.</p></div><div class="footer-links"><div><b>Shop</b><a href="shop.html?category=subscriptions">Subscriptions</a><a href="shop.html?category=software">Software</a><a href="shop.html?category=combos">Combo Packs</a></div><div><b>Help</b><a href="about.html">About us</a><a href="contact.html">Contact</a><a href="legal.html">Policies</a></div></div></div><div class="shell footer-bottom"><span>© 2026 BuyFinix · Bangladesh 🇧🇩</span><nav><a href="legal.html#login">Login Terms</a><a href="legal.html#terms">Terms</a><a href="legal.html#refund">Refund Policy</a></nav></div></footer><nav class="mobile-bottom"><a href="index.html">⌂<span>Home</span></a><a href="shop.html">▦<span>Shop</span></a><a href="account.html#credentials">▣<span>My Credentials</span></a><a href="account.html">♙<span>Account</span></a></nav><div class="global-search-layer" id="global-search-layer" aria-hidden="true"><div class="global-search-box"><div><input id="global-search-input" placeholder="Search Netflix, Spotify, software..." aria-label="Search products"><button id="global-search-close">Cancel</button></div><p class="search-label">MATCHING PLANS</p><div class="search-results" id="global-search-results"></div></div></div><aside class="cart-drawer" id="global-cart-drawer"><div class="cart-head"><b>Your cart</b><button id="global-cart-close" aria-label="Close cart">×</button></div><div id="global-cart-items"></div><div class="cart-total"><span>Subtotal</span><b id="global-cart-total">৳0</b></div><a class="checkout" href="cart.html">View cart &amp; checkout</a></aside><div class="mobile-menu" id="global-mobile-menu"><button id="global-menu-close" aria-label="Close menu">×</button><a href="index.html">Home</a><a href="shop.html">Shop</a><a href="account.html">My Account</a><a href="about.html">About Us</a><a href="contact.html">Contact Us</a><a href="legal.html">Terms &amp; Policies</a></div><div class="scrim" id="global-scrim"></div>`}
function bfLayout(content,wide=false){document.body.innerHTML=bfHeader()+`<main class="${wide?'':'shell '}page-shell">${content}</main>`+bfFooter();bfBindGlobal()}
function bfBindGlobal(){const layer=document.querySelector('#global-search-layer'),drawer=document.querySelector('#global-cart-drawer'),menu=document.querySelector('#global-mobile-menu'),scrim=document.querySelector('#global-scrim'),close=()=>{drawer?.classList.remove('open');menu?.classList.remove('open');scrim?.classList.remove('open');document.body.classList.remove('no-scroll')};document.querySelector('#global-search')?.addEventListener('click',()=>{layer.classList.add('open');layer.setAttribute('aria-hidden','false');bfGlobalSearch('');setTimeout(()=>document.querySelector('#global-search-input')?.focus(),50)});document.querySelector('#global-search-close')?.addEventListener('click',()=>{layer.classList.remove('open');layer.setAttribute('aria-hidden','true')});document.querySelector('#global-search-input')?.addEventListener('input',e=>bfGlobalSearch(e.target.value));document.querySelector('#global-cart')?.addEventListener('click',()=>{bfRenderDrawer();drawer.classList.add('open');scrim.classList.add('open');document.body.classList.add('no-scroll')});document.querySelector('#global-cart-close')?.addEventListener('click',close);document.querySelector('#global-menu')?.addEventListener('click',()=>{menu.classList.add('open');scrim.classList.add('open')});document.querySelector('#global-menu-close')?.addEventListener('click',close);scrim?.addEventListener('click',close);document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();layer?.classList.remove('open')}})}
function bfGlobalSearch(q){const term=q.trim().toLowerCase(),list=term?BF_PRODUCTS.filter(p=>p.name.toLowerCase().includes(term)||p.group.includes(term)):BF_PRODUCTS.slice(0,6),box=document.querySelector('#global-search-results');if(box)box.innerHTML=list.length?list.map(p=>`<a href="product.html?id=${p.id}"><span style="background:${p.color}">${p.mark}</span><b>${p.name}<small>${p.group} · ${p.stock?'In stock':'Sold out'}</small></b><strong>${bfMoney(p.price)}</strong></a>`).join(''):'<div class="empty-state"><b>No matching plans</b><p>Try a product or category name.</p></div>'}
function bfRenderDrawer(){const box=document.querySelector('#global-cart-items'),total=bfCart.reduce((n,x)=>n+bfProduct(x.id).price*x.qty,0);if(box)box.innerHTML=bfCart.length?bfCart.map(x=>{const p=bfProduct(x.id);return `<div class="cart-item"><span class="cart-thumb" style="background:${p.color}">${p.mark}</span><span><b>${p.name}</b><small>${x.duration} · Qty ${x.qty}</small></span><b>${bfMoney(p.price*x.qty)}</b></div>`}).join(''):'<div class="empty-state"><b>Your cart is empty</b><p>Add a plan to get started.</p></div>';const t=document.querySelector('#global-cart-total');if(t)t.textContent=bfMoney(total)}
function bfCard(p){return `<article class="product-card"><a class="product-art" href="product.html?id=${p.id}" style="background:linear-gradient(145deg,${p.color},#172217)"><span class="instant-tag">${p.stock?'⚡ INSTANT':'SOLD OUT'}</span><span class="product-mark">${p.mark}</span></a><div class="product-info"><h4><a href="product.html?id=${p.id}">${p.name}</a></h4><div class="price"><b>${bfMoney(p.price)}</b><span>/mo</span><del>${bfMoney(p.old)}</del></div><div class="card-actions"><button data-add="${p.id}" ${p.stock?'':'disabled'}>＋</button><a class="buy" href="product.html?id=${p.id}">${p.stock?'Buy now':'View plan'}</a></div></div></article>`}
function bfShop(){const params=new URLSearchParams(location.search),state={q:params.get('q')||'',category:params.get('category')||'all',sort:params.get('sort')||'featured',max:Number(params.get('max'))||2500,page:Number(params.get('page'))||1};bfLayout(`<section class="shop-hero"><p class="kicker">BUYFINIX CATALOGUE</p><h1>Find your next <em>plan.</em></h1><p>Premium digital subscriptions and software, priced for Bangladesh.</p></section><section class="shop-surface"><div class="category-tabs" id="category-tabs">${['all','subscriptions','combos','software','music','adult','more'].map(x=>`<button data-category="${x}">${x==='all'?'All':x==='combos'?'Combo Packs':x[0].toUpperCase()+x.slice(1)}</button>`).join('')}</div><div class="toolbar premium-toolbar"><label class="search-field">⌕<input id="shop-search" value="${state.q}" placeholder="Search plans..." aria-label="Search plans"></label><select id="shop-sort" aria-label="Sort products"><option value="featured">Featured</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option><option value="stock">Availability</option></select><label class="price-field">Up to <b id="max-label">${bfMoney(state.max)}</b><input id="shop-max" type="range" min="200" max="2500" step="100" value="${state.max}"></label><button class="clear-filter" id="clear-filters">Clear filters</button></div><div class="catalog-meta"><p id="product-count">Loading plans…</p><span>Instant and manual-delivery items are clearly marked</span></div><div class="product-grid" id="shop-grid"><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div><div class="pagination" id="pagination"></div></section>`);const search=document.querySelector('#shop-search'),sort=document.querySelector('#shop-sort'),range=document.querySelector('#shop-max'),tabs=document.querySelector('#category-tabs'),grid=document.querySelector('#shop-grid'),perPage=8;sort.value=state.sort;const update=()=>{state.q=search.value.trim();state.sort=sort.value;state.max=Number(range.value);document.querySelector('#max-label').textContent=bfMoney(state.max);let list=BF_PRODUCTS.filter(p=>(state.category==='all'||p.group===state.category)&&p.name.toLowerCase().includes(state.q.toLowerCase())&&p.price<=state.max);if(state.sort==='low')list.sort((a,b)=>a.price-b.price);if(state.sort==='high')list.sort((a,b)=>b.price-a.price);if(state.sort==='stock')list.sort((a,b)=>b.stock-a.stock);const pages=Math.max(1,Math.ceil(list.length/perPage));state.page=Math.min(state.page,pages);const visible=list.slice((state.page-1)*perPage,state.page*perPage);grid.innerHTML=visible.length?visible.map(bfCard).join(''):'<div class="empty-state grid-empty"><b>No plans match your filters</b><p>Try a different category, search or price range.</p><button id="empty-clear" class="primary-action">Clear filters</button></div>';document.querySelector('#product-count').textContent=`${list.length} plan${list.length===1?'':'s'}`;tabs.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.category===state.category));document.querySelector('#pagination').innerHTML=pages>1?Array.from({length:pages},(_,i)=>`<button data-page="${i+1}" class="${state.page===i+1?'active':''}">${i+1}</button>`).join(''):'';const q=new URLSearchParams();if(state.q)q.set('q',state.q);if(state.category!=='all')q.set('category',state.category);if(state.sort!=='featured')q.set('sort',state.sort);if(state.max<2500)q.set('max',state.max);if(state.page>1)q.set('page',state.page);history.replaceState(null,'',`${location.pathname}${q.toString()?'?'+q:''}`);document.querySelector('#empty-clear')?.addEventListener('click',clear)};const clear=()=>{state.q='';state.category='all';state.sort='featured';state.max=2500;state.page=1;search.value='';sort.value='featured';range.value=2500;update()};search.oninput=()=>{state.page=1;update()};sort.onchange=()=>{state.page=1;update()};range.oninput=()=>{state.page=1;update()};tabs.onclick=e=>{const b=e.target.closest('[data-category]');if(b){state.category=b.dataset.category;state.page=1;update()}};document.querySelector('#pagination').onclick=e=>{const b=e.target.closest('[data-page]');if(b){state.page=Number(b.dataset.page);update();scrollTo({top:0,behavior:'smooth'})}};document.querySelector('#clear-filters').onclick=clear;update()}
function bfAdd(id,duration='1 Month',qty=1){const p=bfProduct(id);if(!p||!p.stock)return;const key=`${id}-${duration}`,item=bfCart.find(x=>x.key===key);if(item)item.qty+=qty;else bfCart.push({key,id:Number(id),duration,qty});bfSave('buyfinix-cart',bfCart);document.querySelectorAll('[data-cart-count]').forEach(e=>e.textContent=bfCart.reduce((n,x)=>n+x.qty,0));bfToast(`${p.name} added to cart`)}
function bfToast(message){let el=document.querySelector('.toast');if(!el){el=document.createElement('div');el.className='toast';document.body.append(el)}el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)}
function bfProductPage(){const p=bfProduct(new URLSearchParams(location.search).get('id'))||BF_PRODUCTS[0],variants=[['1 Month',p.price],['3 Months',p.price*3-98],['6 Months',p.price*6-295],['12 Months',p.price*12-700]];bfLayout(`<div class="detail-grid"><div class="detail-image" style="background:linear-gradient(145deg,${p.color},#172217)">${p.mark}</div><section class="panel product-panel"><p class="kicker">${p.stock?'⚡ INSTANT DELIVERY':'CURRENTLY SOLD OUT'}</p><h1>${p.name}</h1><div class="price"><b id="detail-price">${bfMoney(p.price)}</b><del>${bfMoney(p.old)}</del></div><p>${p.desc}</p><label class="field-label">Choose plan duration</label><div class="duration-row">${variants.map((v,i)=>`<button class="${i?'':'active'}" data-variant="${v[0]}" data-value="${v[1]}">${v[0]}</button>`).join('')}</div><div class="quantity-row"><button data-qty="-1">−</button><b id="qty">1</b><button data-qty="1">+</button></div><p class="notice">${p.stock?`${p.stock} available · Delivered on WhatsApp after payment confirmation.`:'Leave your WhatsApp number and we will notify you when it returns.'}</p>${p.stock?'<div class="hero-buttons detail-actions"><button class="primary-action" id="add-detail">Add to cart</button><button class="secondary-action" id="buy-detail">Buy now</button></div>':`<form class="restock-form" id="restock-form"><select class="field"><option>+880</option></select><input class="field" inputmode="tel" required placeholder="WhatsApp number"><button class="primary-action">Notify me</button><p class="form-status"></p></form>`}<div class="included"><h3>What’s included</h3><ul><li>Full plan validity</li><li>Setup assistance</li><li>Replacement support during warranty</li></ul><details><summary>Good to know</summary><p>Use the access only as instructed. Device and region requirements may vary by plan.</p></details></div></section></div><section class="related"><div class="group-head"><h2>Related plans</h2><a href="shop.html?category=${p.group}">View all →</a></div><div class="product-grid">${BF_PRODUCTS.filter(x=>x.group===p.group&&x.id!==p.id).slice(0,4).map(bfCard).join('')}</div></section>`);let qty=1,variant=variants[0];document.querySelectorAll('[data-variant]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-variant]').forEach(x=>x.classList.remove('active'));b.classList.add('active');variant=[b.dataset.variant,Number(b.dataset.value)];document.querySelector('#detail-price').textContent=bfMoney(variant[1])});document.querySelectorAll('[data-qty]').forEach(b=>b.onclick=()=>{qty=Math.max(1,Math.min(5,qty+Number(b.dataset.qty)));document.querySelector('#qty').textContent=qty});document.querySelector('#add-detail')?.addEventListener('click',()=>bfAdd(p.id,variant[0],qty));document.querySelector('#buy-detail')?.addEventListener('click',()=>{bfAdd(p.id,variant[0],qty);location.href='checkout.html'});document.querySelector('#restock-form')?.addEventListener('submit',e=>{e.preventDefault();e.target.querySelector('.form-status').textContent='You’re on the restock list.'})}
function bfCartPage(){bfLayout(`<h1 class="page-title">Your cart.</h1><div class="checkout-grid"><section class="panel"><div id="full-cart"></div></section><aside class="panel order-summary"><h2>Order summary</h2><p>Subtotal <b id="cart-subtotal">৳0</b></p><div class="coupon-row"><input class="field" id="coupon" placeholder="Coupon code"><button class="primary-action" id="coupon-apply">Apply</button></div><label class="wallet"><input type="checkbox" id="wallet"> Use wallet credit (৳0)</label><hr><p>Total <b id="cart-grand">৳0</b></p><a class="primary-action checkout-link" href="checkout.html">Continue to checkout</a></aside></div>`);const render=()=>{const box=document.querySelector('#full-cart');if(!bfCart.length){box.innerHTML='<div class="empty-state"><b>Your cart is empty</b><p>Choose a plan to continue.</p><a href="shop.html">Browse plans</a></div>';document.querySelector('.order-summary').hidden=true;return}box.innerHTML=bfCart.map(x=>{const p=bfProduct(x.id);return `<div class="full-cart-row"><span class="cart-thumb" style="background:${p.color}">${p.mark}</span><span><b>${p.name}</b><small>${x.duration}</small></span><div class="mini-qty"><button data-change="-1" data-key="${x.key}">−</button><b>${x.qty}</b><button data-change="1" data-key="${x.key}">+</button></div><strong>${bfMoney(p.price*x.qty)}</strong><button data-delete="${x.key}" aria-label="Remove">×</button></div>`}).join('');const total=bfCart.reduce((n,x)=>n+bfProduct(x.id).price*x.qty,0);document.querySelector('#cart-subtotal').textContent=document.querySelector('#cart-grand').textContent=bfMoney(total);document.querySelectorAll('[data-change]').forEach(b=>b.onclick=()=>{const x=bfCart.find(i=>i.key===b.dataset.key);x.qty+=Number(b.dataset.change);if(x.qty<1)bfCart=bfCart.filter(i=>i!==x);bfSave('buyfinix-cart',bfCart);render()});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{bfCart=bfCart.filter(x=>x.key!==b.dataset.delete);bfSave('buyfinix-cart',bfCart);render()})};render();document.querySelector('#coupon-apply')?.addEventListener('click',()=>bfToast(document.querySelector('#coupon').value.trim().toUpperCase()==='WELCOME10'?'WELCOME10 applied':'Coupon is not valid'))}
function bfCheckout(){if(!bfCart.length){location.href='cart.html';return}const total=bfCart.reduce((n,x)=>n+bfProduct(x.id).price*x.qty,0);bfLayout(`<h1 class="page-title">Secure checkout.</h1><form id="checkout-form" class="checkout-grid"><section class="panel form-grid"><label>Full name<input class="field" name="name" required autocomplete="name"></label><label>Email<input class="field" type="email" name="email" required autocomplete="email"></label><label>Country code<input class="field" value="+880" readonly></label><label>WhatsApp number<input class="field" name="phone" inputmode="tel" required></label><fieldset class="wide payment-methods"><legend>Payment method</legend><label><input type="radio" name="payment" value="bKash" checked> bKash</label><label><input type="radio" name="payment" value="Nagad"> Nagad</label><label><input type="radio" name="payment" value="Rocket"> Rocket</label></fieldset><label class="wide">Transaction ID<input class="field" name="trx" required placeholder="Enter after payment"></label><label class="wide check"><input type="checkbox" required> I accept the terms and digital delivery policy</label></section><aside class="panel"><h2>Your order</h2>${bfCart.map(x=>`<p>${bfProduct(x.id).name} × ${x.qty}<b>${bfMoney(bfProduct(x.id).price*x.qty)}</b></p>`).join('')}<hr><p>Total <b>${bfMoney(total)}</b></p><p class="notice">Payment is manually verified before delivery.</p><button class="primary-action wide-button">Place order</button><p class="form-status" role="status"></p></aside></form>`);document.querySelector('#checkout-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target),orders=bfRead('buyfinix-orders',[]),id='BF-'+Date.now().toString().slice(-8);orders.unshift({id,date:new Date().toISOString(),name:data.get('name'),email:data.get('email'),phone:data.get('phone'),payment:data.get('payment'),trx:data.get('trx'),total,status:'Payment review',items:bfCart});bfSave('buyfinix-orders',orders);bfCart=[];bfSave('buyfinix-cart',bfCart);e.target.innerHTML=`<section class="panel success-card"><span>✓</span><h2>Order received</h2><p>Your order <b>${id}</b> is awaiting manual payment verification.</p><a class="primary-action checkout-link" href="account.html">Track order</a></section>`}}
function bfAccount(){const orders=bfRead('buyfinix-orders',[]);bfLayout(`<section class="account-heading"><p class="kicker">YOUR BUYFINIX</p><h1 class="page-title">Account &amp; orders.</h1><p>Track purchases, wallet credit and delivered credentials in one place.</p></section><section class="panel otp-panel" id="login"><div><p class="kicker">SECURE ACCOUNT ACCESS</p><h2>Email login</h2><p>We’ll send a one-time code when the production email service is connected.</p></div><form id="otp-form" class="otp-form"><label>Email address<input class="field" id="otp-email" type="email" required autocomplete="email" placeholder="you@example.com"></label><button class="primary-action">Send OTP</button><p class="form-status" role="status"></p></form><form id="verify-form" class="otp-form verify-box" hidden><label>6-digit code<input class="field otp-code" id="otp-code" inputmode="numeric" maxlength="6" pattern="[0-9]{6}" required placeholder="000000"></label><button class="primary-action">Verify &amp; continue</button><button type="button" class="resend" id="otp-resend" disabled>Resend in 30s</button><p class="form-status" role="status"></p></form></section><div class="dashboard-grid account-grid"><section class="panel metric-card"><small>WALLET BALANCE</small><h2>৳0</h2><p>Referral credit will appear here.</p></section><section class="panel metric-card"><small>ACTIVE PLANS</small><h2>0</h2><p>No active subscription yet.</p></section><section class="panel" id="credentials"><div class="panel-head"><h2>My Credentials</h2><span class="status-badge neutral">Protected</span></div><div class="empty-state"><b>No credentials delivered</b><p>Secure access details will appear after payment verification.</p></div></section><section class="panel"><div class="panel-head"><h2>Orders</h2><a href="shop.html">Shop plans →</a></div>${orders.length?orders.map(o=>`<div class="order-line"><b>${o.id}</b><span>${new Date(o.date).toLocaleDateString('en-BD')}</span><strong>${bfMoney(o.total)}</strong><em>${o.status}</em></div>`).join(''):'<div class="empty-state"><b>No orders yet</b><p>Your completed checkout orders will appear here.</p></div>'}</section></div>`);const otp=document.querySelector('#otp-form'),verify=document.querySelector('#verify-form'),resend=document.querySelector('#otp-resend');let timer;const countdown=()=>{let left=30;clearInterval(timer);resend.disabled=true;resend.textContent=`Resend in ${left}s`;timer=setInterval(()=>{left--;resend.textContent=left?`Resend in ${left}s`:'Resend OTP';if(!left){clearInterval(timer);resend.disabled=false}},1000)};otp.onsubmit=e=>{e.preventDefault();const button=otp.querySelector('button');button.disabled=true;button.textContent='Sending…';setTimeout(()=>{button.disabled=false;button.textContent='Send OTP';otp.querySelector('.form-status').textContent='Email provider is not connected yet. No code was sent.';verify.hidden=false;countdown()},650)};resend.onclick=countdown;verify.onsubmit=e=>{e.preventDefault();const status=verify.querySelector('.form-status');status.textContent='Connect the production email service to verify real OTP codes.';status.classList.add('error')}}
function bfAdmin(){const orders=bfRead('buyfinix-orders',[]),low=BF_PRODUCTS.filter(p=>p.stock<10);bfLayout(`<div class="admin-heading"><div><p class="kicker">STORE OPERATIONS</p><h1 class="page-title">BuyFinix admin.</h1></div><span class="status-badge warning">Frontend preview</span></div><p class="security-banner">🔒 Production admin access must use server-side authentication and role authorization. Browser data shown here is not a secure database.</p><div class="admin-nav" id="admin-tabs"><button class="active" data-tab="dashboard">Dashboard</button><button data-tab="products">Products</button><button data-tab="orders">Orders</button><button data-tab="customers">Customers</button><button data-tab="coupons">Coupons</button><button data-tab="credentials">Credentials</button><button data-tab="reports">Reports</button></div><div class="admin-metrics"><section class="panel metric-card"><small>TOTAL ORDERS</small><h2>${orders.length}</h2><p>Stored on this device</p></section><section class="panel metric-card"><small>PAYMENT REVIEW</small><h2>${orders.filter(o=>o.status==='Payment review').length}</h2><p>Manual queue</p></section><section class="panel metric-card"><small>CATALOGUE</small><h2>${BF_PRODUCTS.length}</h2><p>Products listed</p></section><section class="panel metric-card"><small>LOW STOCK</small><h2>${low.length}</h2><p>Below 10 units</p></section></div><section class="panel admin-section" data-panel="dashboard"><div class="panel-head"><h2>Manual payment queue</h2><span>${orders.length} orders</span></div>${orders.length?orders.map(o=>`<div class="order-line"><b>${o.id}</b><span>${o.payment} · ${o.trx}</span><strong>${bfMoney(o.total)}</strong><em>${o.status}</em></div>`).join(''):'<div class="empty-state"><b>No pending orders</b><p>Checkout orders awaiting review will appear here.</p></div>'}</section><section class="panel admin-section" data-panel="products" hidden><div class="panel-head"><h2>Products &amp; stock</h2><span>${BF_PRODUCTS.length} products</span></div><div class="admin-product-list">${BF_PRODUCTS.map(p=>`<div><span class="cart-thumb" style="background:${p.color}">${p.mark}</span><b>${p.name}</b><small>${p.group}</small><strong>${bfMoney(p.price)}</strong><em class="${p.stock<10?'low':''}">${p.stock?p.stock+' in stock':'Sold out'}</em></div>`).join('')}</div></section>${[['orders','Orders',orders.length?'Orders are listed in the payment queue.':'No orders yet.'],['customers','Customers','Customer records require a secure backend.'],['coupons','Coupons','WELCOME10 is available in the frontend preview.'],['credentials','Credentials','Never store customer credentials in browser storage.'],['reports','Reports','Production sales reports require verified order data.']].map(x=>`<section class="panel admin-section" data-panel="${x[0]}" hidden><h2>${x[1]}</h2><div class="empty-state"><b>${x[2]}</b><p>This section is prepared for backend integration.</p></div></section>`).join('')}`);const tabs=document.querySelector('#admin-tabs');tabs.onclick=e=>{const b=e.target.closest('[data-tab]');if(!b)return;tabs.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));document.querySelectorAll('[data-panel]').forEach(x=>x.hidden=x.dataset.panel!==b.dataset.tab)}}
function bfAbout(){bfLayout(`<section class="editorial-hero"><p class="kicker">ABOUT BUYFINIX</p><h1>Digital access,<br><em>made simpler.</em></h1><p>BuyFinix helps customers in Bangladesh discover clearly described digital subscriptions and software with straightforward support.</p></section><div class="value-grid"><article class="panel"><span>01</span><h2>Clear before checkout</h2><p>Plan duration, delivery method, price and warranty details should be visible before payment.</p></article><article class="panel"><span>02</span><h2>Support that stays close</h2><p>WhatsApp is the main support channel for delivery questions, setup and eligible replacements.</p></article><article class="panel"><span>03</span><h2>Built for Bangladesh</h2><p>Prices are shown in BDT with familiar local payment methods and plain English instructions.</p></article></div><section class="brand-statement"><p class="kicker">OUR APPROACH</p><h2>Fast when possible.<br><em>Honest always.</em></h2><p>We do not claim that every process is automated. Products and payments that need manual review are clearly identified.</p></section>`)}
function bfContact(){bfLayout(`<section class="editorial-hero compact"><p class="kicker">BUYFINIX SUPPORT</p><h1>How can we <em>help?</em></h1><p>Send an order question or open WhatsApp for faster help. Replace the placeholder link before launch.</p></section><div class="contact-grid"><form class="panel contact-form" id="contact-form"><label>Full name<input class="field" required autocomplete="name"></label><label>Email<input class="field" type="email" required autocomplete="email"></label><label>Order ID <span>Optional</span><input class="field" placeholder="BF-12345678"></label><label>Message<textarea class="field" required rows="5"></textarea></label><button class="primary-action">Send message</button><p class="form-status"></p></form><aside class="support-card"><p class="kicker">QUICK SUPPORT</p><h2>Message us on WhatsApp</h2><p>Use WhatsApp for delivery updates, setup help and warranty questions.</p><a class="primary-action placeholder-link" href="#">Add WhatsApp number</a><small>Editable placeholder — no contact number was available.</small></aside></div>`);document.querySelector('#contact-form').onsubmit=e=>{e.preventDefault();e.target.querySelector('.form-status').textContent='Message saved in this preview. Connect a backend to deliver it.'};document.querySelector('.placeholder-link').onclick=e=>{e.preventDefault();bfToast('Add the official BuyFinix WhatsApp number before launch')}}
function bfLegal(){bfLayout(`<section class="editorial-hero compact"><p class="kicker">POLICIES</p><h1>Clear terms,<br><em>plain language.</em></h1><p>These editable policy summaries should be reviewed with your final business details before launch.</p></section><div class="legal-layout"><nav class="legal-nav"><a href="#login">Login terms</a><a href="#terms">Terms &amp; conditions</a><a href="#refund">Refund policy</a><a href="#privacy">Privacy policy</a></nav><div class="legal-copy"><section id="login"><span>01</span><h2>Login terms</h2><p>Customers must follow the access instructions supplied with an order. Account access may not be resold, shared beyond the purchased plan or used in a way that violates the service provider’s terms.</p></section><section id="terms"><span>02</span><h2>Terms and conditions</h2><p>Product duration, supported region, delivery method and applicable warranty are shown before purchase. Payment is manually reviewed unless a product is clearly marked as automatically verified.</p></section><section id="refund"><span>03</span><h2>Refund and replacement</h2><p>Digital orders are normally final after delivery. Eligible access failures may be resolved through repair, replacement, extension or wallet credit according to the product warranty.</p></section><section id="privacy"><span>04</span><h2>Privacy policy</h2><p>Only information required to process an order and provide support should be collected. BuyFinix should never request banking passwords, card PINs or mobile-financial-service PINs.</p></section></div></div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-add]');if(b)bfAdd(b.dataset.add)});
const page=location.pathname.split('/').pop()||'index.html';if(page==='shop.html')bfShop();else if(page==='product.html')bfProductPage();else if(page==='cart.html')bfCartPage();else if(page==='checkout.html')bfCheckout();else if(page==='account.html')bfAccount();else if(page==='admin.html')bfAdmin();else if(page==='about.html')bfAbout();else if(page==='contact.html')bfContact();else if(page==='legal.html')bfLegal();
